pub fn orient3d_value(a: P3, b: P3, c: P3, d: P3) -> Option<i128> {
    let ba_x = b.x.get().checked_sub(a.x.get())?;
    let ba_y = b.y.get().checked_sub(a.y.get())?;
    let ba_z = b.z.get().checked_sub(a.z.get())?;
    let ca_x = c.x.get().checked_sub(a.x.get())?;
    let ca_y = c.y.get().checked_sub(a.y.get())?;
    let ca_z = c.z.get().checked_sub(a.z.get())?;
    let da_x = d.x.get().checked_sub(a.x.get())?;
    let da_y = d.y.get().checked_sub(a.y.get())?;
    let da_z = d.z.get().checked_sub(a.z.get())?;
    let n_x_1 = Wide32::<3>::product_i64(ca_y, da_z)?;
    let n_x_2 = Wide32::<3>::product_i64(ca_z, da_y)?;
    let n_x = n_x_1.checked_sub(&n_x_2)?;
    let n_y_1 = Wide32::<3>::product_i64(ca_z, da_x)?;
    let n_y_2 = Wide32::<3>::product_i64(ca_x, da_z)?;
    let n_y = n_y_1.checked_sub(&n_y_2)?;
    let n_z_1 = Wide32::<3>::product_i64(ca_x, da_y)?;
    let n_z_2 = Wide32::<3>::product_i64(ca_y, da_x)?;
    let n_z = n_z_1.checked_sub(&n_z_2)?;
    let det_1 = Wide32::<4>::product_by_i64(&n_x, ba_x)?;
    let det_2 = Wide32::<4>::product_by_i64(&n_y, ba_y)?;
    let det_3 = det_1.checked_add(&det_2)?;
    let det_4 = Wide32::<4>::product_by_i64(&n_z, ba_z)?;
    let det = det_3.checked_add(&det_4)?;
    det.to_i128()
}

/// `incircle`'s exact value in width-aware limbs (chapter 23.3): each step in `i64`, or in a
