    let s_4 = Wide32::<4>::product_by_i64(&nz, p_z)?;
    let s_5 = s_3.checked_add(&s_4)?;
    let d = Wide32::<4>::from_i128(within(d, 125)?)?;
    let s = s_5.checked_add(&d)?;
